from pathlib import Path
ROOT=Path(r'C:\Users\gabor\code\playi');OUT=Path(__file__).parent/'product'
def edit(p,fn):
    f=OUT/p;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(fn((ROOT/p).read_text(encoding='utf-8')),encoding='utf-8',newline='\n')
edit('web/app.js',lambda s:s.replace("import {LIMITS,TIMES}", "import {CONNECT_LIMITS,CONNECT_TIMES} from './connect4-runtime.js';\nimport {LIMITS,TIMES}").replace('planning_time_ms:TIMES[9]}', 'planning_time_ms:TIMES[9],connect4_nodes:CONNECT_LIMITS[9],connect4_time_ms:CONNECT_TIMES[9],connect4_target_depth:20}').replace('architecture:[1912,48,48,818],files:1', "architecture:[1912,48,48,818],position_head:{game:'connect4',features:32,outputs:1},files:1").replace('m.core.w.length+m.core.b.length;', 'm.core.w.length+m.core.b.length+(m.positionHead?.weights.length??0);').replace('async function initialize(){render();preset();drawLoss();try{db=await openDB();const stored=await storedModel(\'garry\');if(stored)try{useGarry(stored);}catch{}if(!general){const response=await fetch(\'models/garry.json\');if(!response.ok)throw Error(\'Garry indisponible\');useGarry(await response.json());}', '''async function initialize(){render();preset();drawLoss();try{db=await openDB();const stored=await storedModel('garry');let shipped=null;try{const response=await fetch('models/garry.json');if(response.ok)shipped=await response.json();}catch{}if(stored)try{useGarry(stored);if(stored.format==='garry-mlp-v1'&&shipped?.position_head)general.positionHead=structuredClone(shipped.position_head);}catch{}if(!general){if(!shipped)throw Error('Garry indisponible');useGarry(shipped);}'''))
edit('logic_arena/harness.py',lambda s:s.replace('    from .planner import LIMITS, TIMES', '    from .planner import LIMITS, TIMES\n    from .connect4_wasm import CONNECT_LIMITS,CONNECT_TIMES').replace('"architecture":[1912,48,48,818],"files":1', '"architecture":[1912,48,48,818],"position_head":{"game":"connect4","features":32,"outputs":1},"files":1').replace('"planning_time_ms":TIMES[-1]}', '"planning_time_ms":TIMES[-1],"connect4_nodes":CONNECT_LIMITS[-1],"connect4_time_ms":CONNECT_TIMES[-1],"connect4_target_depth":20}'))
edit('web/index.html',lambda s:s.replace('Les connaissances des six jeux réunies dans un modèle unique.', 'Un modèle unique. Au niveau 10, priorité à la recherche du meilleur coup.').replace('134 258 paramètres','134 290 paramètres').replace('Les dix niveaux règlent le budget de planification et changent la température de sélection, de l’exploration au choix du score maximal. Les six styles ajoutent de légères préférences sur les coups visibles.', 'Le niveau 10 cherche le meilleur coup avec le budget maximal. Au Puissance 4, il vise 20 demi-coups et dispose de deux secondes par décision ; la profondeur réellement atteinte est affichée. Les niveaux 0 à 9 sélectionnent des rangs plus faibles parmi les coups évalués. Le niveau 0 choisit le pire coup selon l’analyse disponible. Des coups équivalents peuvent partager le même niveau.').replace('Un encodeur, un module central et une sortie communs', 'Un encodeur, un module central et une politique communs'))
# Keep experiment labels attached to the actual software version.
for p in ('examples/train_garry_curriculum.py','examples/train_garry_guarded.py','examples/fuse_garry.py','examples/benchmark_garry.mjs'):
    edit(p,lambda s:s.replace("'software_version':'2.0.0'","'software_version':'3.0.0'").replace("version:'2.0.0'","version:'3.0.0'").replace("'version':'2.0.0'","'version':'3.0.0'"))
# Existing benchmark entry points must exercise the active learned head and
# the same 20-ply profile used in play, not an implicit untrained evaluator.
for p in ('examples/benchmark_garry.mjs','examples/compare_garry_checkpoints.mjs'):
    source=(OUT/p).read_text(encoding='utf-8') if (OUT/p).exists() else (ROOT/p).read_text(encoding='utf-8')
    source=source.replace('{timeMs:10000}', '{timeMs:10000,maxDepth:20,positionHead:model.positionHead}')
    f=OUT/p;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(source,encoding='utf-8')
